(function(){let next=1,worker;const pending=new Map();async function trace(image,{colors=0,detail=1024}={}){const ratio=Math.min(1,detail/Math.max(image.width,image.height)),canvas=off(Math.max(1,Math.round(image.width*ratio)),Math.max(1,Math.round(image.height*ratio))),context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height),options={colors,outputWidth:image.width,outputHeight:image.height};if(typeof Worker==='undefined')return FragmentVectorize.trace(pixels,options);if(!worker){worker=new Worker('vector-worker.js?v=1317');worker.onmessage=e=>{const job=pending.get(e.data.id);if(!job)return;pending.delete(e.data.id);e.data.error?job.reject(Error(e.data.error)):job.resolve(e.data.result)};worker.onerror=()=>{for(const job of pending.values())job.reject(Error('Не удалось подготовить SVG'));pending.clear();worker.terminate();worker=null}}const id=next++;return new Promise((resolve,reject)=>{pending.set(id,{resolve,reject});worker.postMessage({id,image:pixels,options},[pixels.data.buffer])})}window.FragmentVector={trace};})();
